        events_by_x[e].append((0, p))

    points = sorted(events_by_x.keys())
    active = defaultdict(int)
    max_heap = []

    result = []
    last = None

    for i, x in enumerate(points):
        # Process all events at this point: ends first, then starts
        for typ, p in sorted(events_by_x[x]):
            if typ == 0:
                active[p] -= 1
            else:
                active[p] += 1
                heappush(max_heap, -p)

        # If there is a next point, we can form a segment [x, nxt)
        if i < len(points) - 1:
            nxt = points[i + 1]
            # Remove stale maxima from the heap
            while max_heap and active[-max_heap[0]] == 0:
                heappop(max_heap)

            if max_heap:  # at least one interval covers (x, nxt)
