    if not intervals:
        return []

    import heapq
    from itertools import groupby

    events = []
    for s, e, p in intervals:
        # end event type 0, start event type 1
        # at the same coordinate, ends are processed before starts
        events.append((s, 1, p))
        events.append((e, 0, p))
    events.sort(key=lambda x: (x[0], x[1]))

    counts = {}
    heap = []

    def add(p):
        counts[p] = counts.get(p, 0) + 1
        heapq.heappush(heap, -p)

    def remove(p):
        counts[p] -= 1

    def max_prio():
        while heap and counts.get(-heap[0], 0) == 0:
            heapq.heappop(heap)
        return -heap[0] if heap else None

    output = []
    prev_start = None
    prev_prio = None

    for coord, grp in groupby(events, key=lambda x: x[0]):
        for _, typ, p in grp:
            if typ == 0:   # end
                remove(p)
            else:          # start
                add(p)

        new_prio = max_prio()
        if prev_prio is not None:
            if new_prio != prev_prio:
                output.append((prev_start, coord, prev_prio))
                prev_start = coord
                prev_prio = new_prio
        else:
            if new_prio is not None:
                prev_start = coord
                prev_prio = new_prio

