class TokenBucket:
    def __init__(self, capacity: float, refill_rate: float):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self.tokens = capacity          # start FULL
        self.last_time = None           # not set until first allow()

    def allow(self, n: float = 1.0, now: float = 0.0) -> bool:
        # First call establishes the baseline time; no refill.
        if self.last_time is None:
            self.last_time = now
        else:
            elapsed = now - self.last_time
            if elapsed < 0:
                elapsed = 0.0           # time went backwards -> treat as zero
            # Continuous refill: add elapsed * refill_rate, capped at capacity
            self.tokens = min(self.capacity,
                              self.tokens + elapsed * self.refill_rate)
            self.last_time = now

        if self.tokens >= n:
            self.tokens -= n
            return True
        return False

