            elif ev[0] == 'i_e':
                removed.add(ev[2])
            elif ev[0] == 'c_s':
                cancel_cnt += 1
            else:  # 'c_e'
                cancel_cnt -= 1

        if i == len(times) - 1:
            break
        nxt = times[i + 1]
        if t == nxt:
            continue

        # Get current maximum priority
        while heap and heap[0][1] in removed:
            heapq.heappop(heap)
        cur_prio = -heap[0][0] if heap else None

        if cur_prio is not None and cancel_cnt == 0:
            # Extend last segment if possible
