            _, _, p = events[i]
            count[p] = count.get(p, 0) - 1
            i += 1
        # Process all starts at x
        while i < n and events[i][0] == x and events[i][1] == 1:
            _, _, p = events[i]
            count[p] = count.get(p, 0) + 1
            if count[p] == 1:
                heapq.heappush(heap, -p)
            i += 1

        # Clean up heap
        while heap and count.get(-heap[0], 0) == 0:
            heapq.heappop(heap)

        new_max = -heap[0] if heap else None

        if current_prio != new_max:
            if current_prio is not None:
                resolved.append((current_start, x, current_prio))
            current_start = x if new_max is not None else None
            current_prio = new_max

    # (After the last coordinate the active set is guaranteed empty, so no hanging segment)

    # Step 2: Merge cancel intervals
