        # Coalesce touching same-prio segments just in case
        merged_res = []
        for s, e, p in resolved:
            if merged_res and merged_res[-1][1] == s and merged_res[-1][2] == p:
                merged_res[-1] = (merged_res[-1][0], e, p)
            else:
                merged_res.append((s, e, p))
        return merged_res

    sorted_cancels = sorted(cancels, key=lambda c: c[0])
    merged_cancels = []
    for cs, ce in sorted_cancels:
        if not merged_cancels:
            merged_cancels.append([cs, ce])
        else:
