from collections import defaultdict

def merge_busy2(intervals, cancels):
    # Step 1: Build the resolved timeline with maximum priority.
    if not intervals:
        return []

    # Collect all distinct times from interval boundaries.
    times = set()
    for s, e, _ in intervals:
        times.add(s)
        times.add(e)
    times = sorted(times)

    # Group events by time: (type, priority), type +1 for start, -1 for end.
    events = defaultdict(list)
    for s, e, p in intervals:
        events[s].append((1, p))
        events[e].append((-1, p))

    heap = []                     # max-heap storing -priority
    removals = defaultdict(int)   # lazy removal counter
    raw_segments = []             # segments before coalescing

    # Sweep over consecutive critical points.
    for i in range(len(times) - 1):
        t = times[i]
        t_next = times[i + 1]

        # Process all events at time t.
        for typ, p in events[t]:
            if typ == 1:
                heapq.heappush(heap, -p)
            else:
                removals[p] += 1

        # Lazy deletion: discard invalid top elements.
        while heap and removals[-heap[0]] > 0:
            top_p = -heap[0]
            heapq.heappop(heap)
            removals[top_p] -= 1

        if heap:
            max_p = -heap[0]
            raw_segments.append([t, t_next, max_p])

    # Coalesce adjacent segments with the same priority.
    segments = []
    for seg in raw_segments:
        if segments and segments[-1][2] == seg[2] and segments[-1][1] == seg[0]:
            segments[-1][1] = seg[1]
        else:
            segments.append(seg)

    # If there are no cancels, the resolved timeline is the answer.
    if not cancels:
        return [tuple(s) for s in segments]

    # Step 2: Merge overlapping or touching cancels into a disjoint union.
    sorted_cancels = sorted(cancels, key=lambda x: x[0])
    merged_cancels = []
    for c_s, c_e in sorted_cancels:
        if not merged_cancels:
            merged_cancels.append([c_s, c_e])
        else:
            last = merged_cancels[-1]
            if c_s <= last[1]:          # overlap or touch
                if c_e > last[1]:
                    last[1] = c_e
            else:
                merged_cancels.append([c_s, c_e])

    # Step 3: Subtract the cancel union from each resolved segment.
    result = []
    i = 0
    n_c = len(merged_cancels)
    for s, e, p in segments:
        # Skip cancels that end at or before the segment start.
        while i < n_c and merged_cancels[i][1] <= s:
            i += 1
        curr = s
        while curr < e:
            if i >= n_c or merged_cancels[i][0] >= e:
                result.append([curr, e, p])
                break
            c_s, c_e = merged_cancels[i]
            if c_s > curr:
                result.append([curr, c_s, p])
            curr = max(curr, c_e)
            if curr >= e:
                break
            # Advance past cancels that are completely processed.
            while i < n_c and merged_cancels[i][1] <= curr:
                i += 1

    # Step 4: Final coalescing of adjacent segments with equal priority.
    final = []
    for seg in result:
        if final and final[-1][2] == seg[2] and final[-1][1] == seg[0]:
            final[-1][1] = seg[1]
        else:
            final.append(seg)

    return [tuple(x) for x in final]

def merge_busy2(intervals, cancels):
    if not intervals:
        return []

    # Step 1: Build the max-priority timeline
    events = []
    for s, e, p in intervals:
        events.append((s, p, 1))   # start
        events.append((e, p, -1))  # end

    # Sort events: time ascending, ends (-1) before starts (1) at the same time
    events.sort(key=lambda x: (x[0], x[2]))

    from collections import defaultdict
    active = defaultdict(int)
    current_max = None
    prev_time = None
    segments = []

    for t, p, d in events:
        if prev_time is not None and t > prev_time:
            if current_max is not None:
                # coalesce adjacent segments with same priority
                if segments and segments[-1][1] == prev_time and segments[-1][2] == current_max:
                    segments[-1][1] = t
                else:
                    segments.append([prev_time, t, current_max])
        # apply event
        if d == 1:
            active[p] += 1
        else:
            active[p] -= 1
            if active[p] == 0:
                del active[p]
        # update current max
        if active:
            current_max = max(active.keys())
        else:
            current_max = None
        prev_time = t

    # Step 2: Merge cancel intervals (including touching cancels)
    merged_cancels = []
    for cs, ce in sorted(cancels):
        if not merged_cancels or cs > merged_cancels[-1][1]:
            merged_cancels.append([cs, ce])
        else:
            if ce > merged_cancels[-1][1]:
                merged_cancels[-1][1] = ce

    # Step 3: Subtract merged cancels from the resolved segments
    final_segments = []
    i = 0
    n = len(merged_cancels)
    for s, e, p in segments:
        cur = s
        while i < n and merged_cancels[i][0] < e:
            cs, ce = merged_cancels[i]
            if ce <= cur:
                i += 1
                continue
            if cs >= e:
                break
            if cs > cur:
                final_segments.append([cur, cs, p])
            cur = max(cur, ce)
            if cur >= e:
                break
            i += 1
        if cur < e:
            final_segments.append([cur, e, p])

    # Step 4: Final coalesce of adjacent segments with equal priority
    if not final_segments:
        return []

    res = []
    cur_s, cur_e, cur_p = final_segments[0]
    for s, e, p in final_segments[1:]:
        if s == cur_e and p == cur_p:
            cur_e = e
        else:
            res.append((cur_s, cur_e, cur_p))
            cur_s, cur_e, cur_p = s, e, p
    res.append((cur_s, cur_e, cur_p))

    return res

