                'parent': parent,
                'tokens': float(cap),   # start full
                'last': None            # never updated
            }
            if parent is None:
                root_count += 1
        if root_count != 1:
            raise ValueError("Exactly one node must have parent None (root)")
        # verify all parents exist (except root)
        for name, nd in self._nodes.items():
            p = nd['parent']
            if p is not None and p not in self._nodes:
                raise ValueError(f"Parent '{p}' of node '{name}' not found")

    def allow(self, name: str, n: float = 1.0, now: float = 0.0) -> bool:
        if name not in self._nodes:
            raise KeyError(f"Unknown node '{name}'")

        # collect path from named node up to root
        path = []
        cur = name
        while cur is not None:
            path.append(cur)
            cur = self._nodes[cur]['parent']

        # 1) update every node on the path to time 'now'
        for node in path:
            nd = self._nodes[node]
            if nd['last'] is None:
                nd['last'] = now
                # tokens already at capacity
            else:
                if now > nd['last']:
                    elapsed = now - nd['last']
                    nd['tokens'] = min(nd['cap'], nd['tokens'] + nd['rate'] * elapsed)
                    nd['last'] = now
                # if now <= last, elapsed treated as zero, do nothing

        # 2) check that all have sufficient tokens
        for node in path:
            if self._nodes[node]['tokens'] < n:
                return False   # no debit anywhere

        # 3) success: debit all
        for node in path:
            self._nodes[node]['tokens'] -= n
        return True

class RateTree:
    def __init__(self, spec):
        """
        spec: dict[str, tuple[float, float, str | None]]
            name -> (capacity, refill_rate, parent)
        """
        self.nodes = {}
        for name, (cap, rate, parent) in spec.items():
            if parent is not None and parent not in spec:
                raise ValueError(f"Parent '{parent}' of node '{name}' not found in spec")
            self.nodes[name] = {
                'cap': cap,
                'rate': rate,
                'parent': parent,
                'avail': cap,          # starts full
                'last_update': 0.0
            }
        roots = [n for n, nd in self.nodes.items() if nd['parent'] is None]
        if len(roots) != 1:
            raise ValueError("Exactly one root node required")

    def allow(self, name, n=1.0, now=0.0):
        """
        Attempt to consume n tokens from node `name` and all its ancestors.
        Returns True if successful, False otherwise (no state changed).
        """
        if name not in self.nodes:
            raise KeyError(f"Node '{name}' not found")

        # collect path from name to root (inclusive)
        path = []
        cur = name
        while cur is not None:
            path.append(cur)
            cur = self.nodes[cur]['parent']

        # first pass: check availability without side-effects
        for node_name in path:
            nd = self.nodes[node_name]
            delta = now - nd['last_update']
            if delta > 0:
                avail = nd['avail'] + delta * nd['rate']
                if avail > nd['cap']:
                    avail = nd['cap']
            else:
                avail = nd['avail']
            if avail < n:
                return False

        # second pass: apply refill and debit
        for node_name in path:
            nd = self.nodes[node_name]
            delta = now - nd['last_update']
            if delta > 0:
                nd['avail'] = min(nd['cap'], nd['avail'] + delta * nd['rate'])
                nd['last_update'] = now
            nd['avail'] -= n

        return True

class RateTree:
    def __init__(self, spec):
        self.nodes = {}
        for name, (capacity, refill_rate, parent) in spec.items():
            self.nodes[name] = {
                'capacity': float(capacity),
                'rate': float(refill_rate),
                'available': float(capacity),  # starts full
                'last_update': 0.0,
                'parent': parent
            }

    def allow(self, name, n=1.0, now=0.0):
        if name not in self.nodes:
            raise ValueError(f"Node '{name}' not found in spec")

        # collect path from named node up to root
        path = []
        cur_name = name
        while cur_name is not None:
            node = self.nodes[cur_name]
            path.append(node)
            cur_name = node['parent']

        # refill every touched node (if now is in the future)
        for node in path:
            if now > node['last_update']:
                elapsed = now - node['last_update']
                node['available'] = min(node['available'] + elapsed * node['rate'], node['capacity'])
                node['last_update'] = now
            # if now <= last_update: elapsed = 0, no refill, leave last_update unchanged

        # all nodes on the path must have at least n tokens
        for node in path:
            if node['available'] < n:
                return False

        # success: debit n from every node on the path
        for node in path:
            node['available'] -= n
        return True

import csv
import re
from datetime import datetime

def parse_ledger(text):
    # Mapping for conversion rates
    rates = {"INR": 1.0, "USD": 83.5, "EUR": 90.25}
    # Set to track seen (date, description, amount_inr)
    seen = set()
    parsed_rows = []

    # Month abbreviations
    months_abbr = "Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec"
    # Pattern for "Mon D, YYYY," (the trailing comma is the field separator)
    mon_comma_pat = re.compile(r'^(' + months_abbr + r') (\d{1,2}), (\d{4}),')

    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue

        date_str = None
        rest_fields = None

        # Check for the special "Mon D, YYYY" date form (comma inside date)
        m = mon_comma_pat.match(line)
        if m:
            # Construct date string "Mon D, YYYY"
            date_str = f"{m.group(1)} {m.group(2)}, {m.group(3)}"
            rest = line[m.end():]   # the part after the field-separating comma
            try:
                reader = csv.reader([rest], quotechar='"', skipinitialspace=True)
                fields = next(reader)
            except StopIteration:
                continue
            if len(fields) != 3:
                continue
            desc, amount_str, currency = fields
        else:
            # Standard case: no embedded comma in date
            try:
                reader = csv.reader([line], quotechar='"', skipinitialspace=True)
                fields = next(reader)
            except StopIteration:
                continue
            if len(fields) != 4:
                continue
            date_str, desc, amount_str, currency = fields

        # --- Normalize date ---
        dt = None
        if re.match(r'^\d{2}/\d{2}/\d{4}$', date_str):
            try:
                dt = datetime.strptime(date_str, "%d/%m/%Y")
            except ValueError:
                continue
        elif re.match(r'^\d{4}-\d{2}-\d{2}$', date_str):
            try:
                dt = datetime.strptime(date_str, "%Y-%m-%d")
            except ValueError:
                continue
        elif re.match(r'^\d{1,2} (' + months_abbr + r') \d{4}$', date_str):
            try:
                dt = datetime.strptime(date_str, "%d %b %Y")
            except ValueError:
                continue
        elif re.match(r'^(' + months_abbr + r') \d{1,2}, \d{4}$', date_str):
            try:
                dt = datetime.strptime(date_str, "%b %d, %Y")
            except ValueError:
                continue
        else:
            continue

        iso_date = dt.strftime("%Y-%m-%d")

        # --- Clean description ---
        desc = desc.strip()

        # --- Parse amount ---
        amount_str = amount_str.strip()
        negative = False

        # Parentheses → negative
        if amount_str.startswith('(') and amount_str.endswith(')'):
            negative = True
            amount_str = amount_str[1:-1].strip()
        elif amount_str.endswith(' DR'):
            negative = True
            amount_str = amount_str[:-3].strip()

        # Remove currency symbol (₹, $, €) if present at the beginning
        if amount_str and amount_str[0] in '₹$€':
            amount_str = amount_str[1:].lstrip()

        # Remove thousands commas
        amount_str = amount_str.replace(',', '')

        try:
            amount = float(amount_str)
        except ValueError:
            continue

        if negative:
            amount = -amount

        # --- Convert to INR ---
        currency = currency.strip()
        if currency not in rates:
            continue
        amount_inr = round(amount * rates[currency], 2)

        # --- Deduplicate ---
        key = (iso_date, desc, amount_inr)
        if key in seen:
            continue
        seen.add(key)
        parsed_rows.append({
            "date": iso_date,
            "description": desc,
            "amount_inr": amount_inr
        })

    # --- Sort: date ascending, abs(amount_inr) descending, stable (preserves original order for ties) ---
    parsed_rows.sort(key=lambda r: (r["date"], -abs(r["amount_inr"])))
    return parsed_rows

class LRUCache:
    def __init__(self, capacity, ttl):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}     # key -> (value, stored_time)
        self._order = []    # least-recently-used first

    def _expired(self, key, now):
        return now - self._data[key][1] > self.ttl

    def _purge(self, now):
        expired = [k for k in self._data if self._expired(k, now)]
        for k in expired:
            del self._data[k]
        self._order = [k for k in self._order if k not in expired]

    def put(self, key, value, now):
        if key in self._data:
            # Update existing key and make it most-recently-used
            self._data[key] = (value, now)
            self._order.remove(key)
            self._order.append(key)
            return

        # New key
        if len(self._data) >= self.capacity:
            self._purge(now)
        if len(self._data) >= self.capacity:
            victim = self._order.pop(0)   # least-recently-used
            del self._data[victim]
        self._data[key] = (value, now)
        self._order.append(key)

    def get(self, key, now):
        if key not in self._data:
            return None
        if self._expired(key, now):
            # Remove expired entry and return None
            del self._data[key]
            self._order.remove(key)
            return None
        # Make most-recently-used
        self._order.remove(key)
        self._order.append(key)
        return self._data[key][0]

    def size(self, now):
        return sum(1 for k in self._data if not self._expired(k, now))

