        if key in self._data:
            # Update existing entry: new value and time, then make MRU
            self._data[key] = (value, now)
            self._make_mru(key)
            return

        # New key: if at capacity, first drop all expired entries
        if len(self._data) >= self.capacity:
            self._purge(now)
        # If still at capacity, evict the least-recently-used key
        if len(self._data) >= self.capacity:
            victim = self._order.pop(0)   # LRU is at index 0
            del self._data[victim]

        # Insert the new entry (becomes MRU)
        self._data[key] = (value, now)
        self._order.append(key)

    def get(self, key, now):
        if key not in self._data:
            return None
        if self._expired(key, now):
            # Expired entries are treated as absent
            return None
        # Non-expired: make MRU and return value
        self._make_mru(key)
        return self._data[key][0]

