def max_load(events):
    if not events:
        return (0, 0)

    # Each event contributes +w at start and -w at end
    deltas = []
    for s, e, w in events:
        deltas.append((s, w))
        deltas.append((e, -w))

    # Sort by time ascending; for equal times, process ends (-w) before starts (+w)
    deltas.sort(key=lambda x: (x[0], x[1]))

    max_peak = 0
    peak_time = 0
    curr = 0
    i = 0
    n = len(deltas)

    while i < n:
        t = deltas[i][0]
        # Apply all changes occurring at time t
        while i < n and deltas[i][0] == t:
            curr += deltas[i][1]
            i += 1
        # After applying all changes at time t, curr is the load on [t, next_time)
        if curr > max_peak:
            max_peak = curr
            peak_time = t

    return (max_peak, peak_time)

def max_load(events):
    if not events:
        return (0, 0)

    # Net change in load at each time point
    delta = {}
    for start, end, weight in events:
        delta[start] = delta.get(start, 0) + weight
        delta[end] = delta.get(end, 0) - weight

    # Sort all distinct times where load changes
    times = sorted(delta.keys())

    current_load = 0
    peak = 0
    peak_time = 0

    for t in times:
        current_load += delta[t]
        if current_load > peak:
            peak = current_load
            peak_time = t

    return (peak, peak_time)

def elapsed_seconds(tz_name, start, end):
    from datetime import datetime, timedelta, timezone
    from zoneinfo import ZoneInfo, AmbiguousTimeError, NonExistentTimeError

    tz = ZoneInfo(tz_name)
    fmt = "%Y-%m-%d %H:%M:%S"

    def localize(dt_naive):
        """Return an aware datetime in UTC for the given naive local wall-clock time,
        respecting the resolution rules:
          - ambiguous (fall-back) -> earlier occurrence (fold=0)
          - nonexistent (spring-forward) -> UTC offset immediately before the jump.
        """
        try:
            aware = dt_naive.replace(tzinfo=tz)
        except AmbiguousTimeError:
            aware = dt_naive.replace(fold=0, tzinfo=tz)
        except NonExistentTimeError:
            # step backwards to find a valid local time and its offset
            probe = dt_naive
            while True:
                try:
                    offset = tz.utcoffset(probe)
                    break
                except NonExistentTimeError:
                    probe -= timedelta(minutes=30)
            # local = UTC + offset  =>  UTC = local - offset
            utc_naive = dt_naive - offset
            return utc_naive.replace(tzinfo=timezone.utc)
        return aware.astimezone(timezone.utc)

    start_dt = datetime.strptime(start, fmt)
    end_dt = datetime.strptime(end, fmt)

    start_utc = localize(start_dt)
    end_utc = localize(end_dt)

    delta = end_utc - start_utc
    return delta.total_seconds()

def truncate_graphemes(s, n):
    import unicodedata

    clusters = []
    current = []          # characters of the cluster being built
    force_join = False    # next code point must join the current cluster (because of a preceding ZWJ)

    for c in s:
        cat = unicodedata.category(c)
        is_mark = (cat == "Mn")
        is_zwj = (c == "\u200D")

        if force_join:
            # This code point is forced into the current cluster.
            current.append(c)
            force_join = False
            if is_zwj:
                force_join = True   # a forced ZWJ still forces the following code point
            continue

        # No force in effect — decide based on code point type.
        if is_mark:
            if current:
                current.append(c)
            else:
                # Combining mark at the very beginning forms its own cluster.
                current = [c]
        elif is_zwj:
            if current:
                current.append(c)
            else:
                # ZWJ at the beginning starts a new cluster.
                current = [c]
            force_join = True
        else:
            # Any other code point starts a new cluster.
            if current:
                clusters.append("".join(current))
            current = [c]
            # force_join stays False

    if current:
        clusters.append("".join(current))

    if len(clusters) <= n:
        return s
    else:
        return "".join(clusters[:n]) + "..."

import unicodedata

def truncate_graphemes(s, n):
    """Return s truncated to at most n user-perceived characters (clusters).

    Clusters are built according to the rules:
    - Combining marks (Mn) attach to the preceding cluster (or form their own at start).
    - ZERO WIDTH JOINER (U+200D) attaches to the current cluster and forces the next
      code point (plus any following Mn) into the same cluster. ZWJ chains.
    - All other code points start a new cluster.
    """
    if not s:
        return s

    clusters = []
    current = []
    force_next = False
    ZWJ = '\u200d'

    for i, cp in enumerate(s):
        if i == 0:
            current.append(cp)
            if cp == ZWJ:
                force_next = True
            continue

        if force_next:
            current.append(cp)
            if cp == ZWJ:
                force_next = True
            else:
                force_next = False
        else:
            if cp == ZWJ:
                current.append(cp)
                force_next = True
            elif unicodedata.category(cp) == 'Mn':
                current.append(cp)
                # force_next remains False
            else:
                clusters.append(''.join(current))
                current = [cp]
                if cp == ZWJ:
                    force_next = True
                else:
                    force_next = False

    clusters.append(''.join(current))

    if len(clusters) <= n:
        return s
    return ''.join(clusters[:n]) + '...'

def find_all_occurrences(text, pattern):
    n = len(text)
    m = len(pattern)
    if m > n:
        return []

    # Build the LPS (longest proper prefix which is also suffix) array for pattern
    lps = [0] * m
    length = 0          # length of previous longest prefix suffix
    i = 1
    while i < m:
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    # Search using the KMP algorithm (supports overlapping matches)
    occurrences = []
    i = 0   # index for text
    j = 0   # index for pattern
    while i < n:
        if text[i] == pattern[j]:
            i += 1
            j += 1

        if j == m:
            # A full match is found, record start index
            occurrences.append(i - j)
            # Prepare to look for overlapping matches
            j = lps[j - 1]

        elif i < n and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return occurrences

