            self.cache = {}
            self._min_len = min_len

        def __call__(self, value):
            if value in self.cache:
                return self.cache[value]
            result = len(value) >= self._min_len
            self.cache[value] = result
            return result

    return [Validator(name, length) for name, length in specs]
